INSERT INTO _spawn_freeze (r, new_id)
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lichen-wood', 'west', 'the-boundary-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sodden-ground', 'west', 'the-dry-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-same-tree', 'west', 'the-ward-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flint-floor', 'west', 'the-mossed-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boundary-bank', 'door', 'The Boundary Bank', 'A bank runs along the edge of the wood here, chest-high and grown over, the boundary somebody once walked to say where the wood they cut ended. Past it nobody cut anything. The coppice stops at the bank as if it had been told to, and on the far side the trunks are too wide to reach round, standing in their own dead leaves.', 0, 0, 'wood', 0, -42, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-bank', 'east', 'the-lichen-wood', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-bank', 'north', 'the-leaning-limes', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dry-rise', 'door', 'The Dry Rise', 'The ground lifts out of the wet by a man''s height over a few dozen paces, and the alders give up and the oaks begin. The soil here is dry and dark and soft with a thousand years of leaf. The water is behind you. What is in front of you was never felled.', 0, 0, 'wood', 0, -49, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-rise', 'east', 'the-sodden-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-rise', 'north', 'the-drowned-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-rise', 'south', 'the-last-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-rise', 'west', 'the-sloe-thicket', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-leaning-limes', 'door', 'The Leaning Limes', 'Limes, broad and old, leaning in over the way from both sides until their crowns meet and lock. In summer the air here hums with something. Now it is only still.', 0, 0, 'wood', 0, -42, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-leaning-limes', 'south', 'the-boundary-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-leaning-limes', 'west', 'the-black-oaks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-leaning-limes', 'north', 'the-owl-oak', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drowned-hollow', 'door', 'The Drowned Hollow', 'A hollow in the floor where water stands a few inches deep over dead leaves, the trees around its rim leaning in. The water is brown and smells of the leaves in it. Prints go in at one side and do not come out the other.', 0, 0, 'wood', 0, -49, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-hollow', 'south', 'the-dry-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-hollow', 'north', 'the-long-fall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-hollow', 'west', 'the-grey-stools', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-last-oak', 'door', 'The Last Oak', 'An oak so big that the trees around it keep their distance, leaving it a ring of open floor. Its lower limbs are as thick as other trees'' trunks and run out level for thirty feet before they turn up. Something sleeps along one of them, by the wear.', 0, 0, 'wood', 0, -49, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-oak', 'north', 'the-dry-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-oak', 'east', 'the-oak-fall-gap', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sloe-thicket', 'door', 'The Sloe Thicket', 'Blackthorn grown up in a thicket under the edge of the canopy, the thorns long and the fruit blue-black and bitter. There is one way through, low, along the ground. It is the way something takes to get from one side to the other.', 0, 0, 'wood', 0, -50, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sloe-thicket', 'east', 'the-dry-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sloe-thicket', 'west', 'the-deep-roots', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-black-oaks', 'door', 'The Black Oaks', 'The bark of the oaks here is black with age and wet, and the moss on their north sides is black too. The light is grey. You could walk past this place three times and not know it was the same place.', 0, 0, 'wood', 0, -43, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-oaks', 'east', 'the-leaning-limes', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-oaks', 'west', 'the-thorn-thicket', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-oaks', 'south', 'the-bent-hazels', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-owl-oak', 'door', 'The Owl Oak', 'An oak so old it has gone hollow from the ground up, its trunk open on one side like a door, the inside floored with pellets and feathers. Something sleeps in it by day. It is not asleep now.', 0, 0, 'wood', 0, -42, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-owl-oak', 'south', 'the-leaning-limes', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-owl-oak', 'east', 'the-mossed-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-owl-oak', 'north', 'the-woodpecker-stand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-long-fall', 'door', 'The Long Fall', 'A tree came down here across the slope and lies the whole length of it, a hundred feet of trunk gone soft and green, with the way running beside it. Halfway along there is a gap where it broke. Something has used the gap.', 0, 0, 'wood', 0, -49, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-fall', 'south', 'the-drowned-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-fall', 'north', 'the-hornets-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-fall', 'west', 'the-elder-brake', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-grey-stools', 'door', 'The Grey Stools', 'Coppice stools of enormous age, each one a ring of grey trunks round an empty centre where the first tree died out, so the floor is dotted with these circles of wood like the bases of towers. You walk between them. You could walk round inside any one.', 0, 0, 'wood', 0, -50, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-stools', 'east', 'the-drowned-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-stools', 'west', 'the-wild-cherry', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-oak-fall-gap', 'door', 'The Oak-Fall Gap', 'Where a great oak fell, it opened a hole in the canopy that has never closed, and the light comes down into it in a single shaft. In the shaft, grass, and foxgloves, and a buzz of insects. Outside it, the dark.', 0, 0, 'wood', 0, -48, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-fall-gap', 'west', 'the-last-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-fall-gap', 'east', 'the-old-boundary-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-deep-roots', 'door', 'The Deep Roots', 'The ground has fallen away from under a row of great trees here and left their roots in the air, a wall of them taller than you, tangled and furred and dripping. Behind them there is a dark you cannot see into.', 0, 0, 'wood', 0, -51, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-roots', 'east', 'the-sloe-thicket', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-thorn-thicket', 'door', 'The Thorn Thicket', 'Blackthorn, old and grey, grown up in a thicket under the canopy edge, the thorns as long as a finger. There is a way through. It is narrow, and the thorns know where it is.', 0, 0, 'wood', 0, -44, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-thicket', 'east', 'the-black-oaks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-thicket', 'north', 'the-hidden-spring', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-thicket', 'west', 'the-old-pollards', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thorn-thicket', 'south', 'the-great-root', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bent-hazels', 'door', 'The Bent Hazels', 'Old hazel under the oaks, overgrown, its stems leaning and crossing in every direction, so the understorey is a lattice you have to thread. The nuts on the floor have all been opened.', 0, 0, 'wood', 0, -43, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bent-hazels', 'north', 'the-black-oaks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bent-hazels', 'south', 'the-grey-mist', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mossed-wall', 'door', 'The Mossed Wall', 'A bank runs through the trees here, straight, waist-high, so overgrown with moss that it looks like a living thing. It was a boundary once. There is nothing on either side of it to say between what.', 0, 0, 'wood', 0, -41, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mossed-wall', 'east', 'the-flint-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mossed-wall', 'west', 'the-owl-oak', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-woodpecker-stand', 'door', 'The Woodpecker Stand', 'Dead limbs here are drilled through and through, and the drumming of whatever drills them comes and goes from tree to tree, always somewhere else, never the tree you are looking at.', 0, 0, 'wood', 0, -42, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-woodpecker-stand', 'south', 'the-owl-oak', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hornets-oak', 'door', 'The Hornets'' Oak', 'A hollow oak with a hum in it, low and steady, coming from somewhere high in the trunk where a split opens into the dark. The ground round its foot is littered with papery grey scraps. You go by it quietly.', 0, 0, 'wood', 0, -49, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hornets-oak', 'south', 'the-long-fall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hornets-oak', 'east', 'the-wet-oaks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-elder-brake', 'door', 'The Elder Brake', 'Elder, grown up wild under a break in the canopy, its stems pale and corky, its smell rank. It is easy to push through and it closes up behind you without a mark. The ground under it is trodden flat.', 0, 0, 'wood', 0, -50, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-elder-brake', 'east', 'the-long-fall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wild-cherry', 'door', 'The Wild Cherry', 'A cherry stands among the oaks, its bark peeling in red-brown bands, its leaves already turned while the oaks are green. Under it the ground is scattered with stones from fruit something ate and spat. Birds go in and out of it all day.', 0, 0, 'wood', 0, -51, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wild-cherry', 'east', 'the-grey-stools', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wild-cherry', 'west', 'the-fungus-fall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wild-cherry', 'north', 'the-holly-tree', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-old-boundary-stone', 'door', 'The Old Boundary Stone', 'A stone stands at the foot of an oak, cut square once and carved with letters that the moss has filled. The oak has grown round it on one side. Whatever line it marked, the wood stopped paying attention to it a very long time ago.', 0, 0, 'wood', 0, -47, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-boundary-stone', 'west', 'the-oak-fall-gap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-boundary-stone', 'east', 'the-black-alder-stand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hidden-spring', 'door', 'The Hidden Spring', 'Water comes up out of the ground here under the roots of a beech, clear and cold and without a sound, and fills a stone basin somebody cut for it once and then forgot. It runs off a dozen paces and goes back into the earth. The ground around it is firm, and flat, and the only open sky for a long way.', 0, 0, 'wood', 0, -44, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hidden-spring', 'south', 'the-thorn-thicket', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hidden-spring', 'east', 'the-leaf-drifts', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hidden-spring', 'west', 'the-moss-boulders', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-old-pollards', 'door', 'The Old Pollards', 'Trees cut once at head height, long ago, and left to grow again from the cut, so each one is a squat trunk with a crown of great limbs sprouting from the top like fingers from a fist. Nobody has cut them in centuries.', 0, 0, 'wood', 0, -45, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-pollards', 'east', 'the-thorn-thicket', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-pollards', 'west', 'the-sunless-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-pollards', 'south', 'the-dappled-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-great-root', 'door', 'The Great Root', 'A single root, as thick as a man, runs over the surface of the ground here for twenty paces from a tree you cannot see the top of. It is worn smooth along its back where things have walked it.', 0, 0, 'wood', 0, -44, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-great-root', 'north', 'the-thorn-thicket', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-great-root', 'south', 'the-ancient-ash', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-grey-mist', 'door', 'The Grey Mist', 'Mist lies between the trees here at every hour, low and white, so you wade through it to the knee and cannot see your own feet. The trunks rise out of it like posts. Sound carries strangely in it.', 0, 0, 'wood', 0, -43, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-mist', 'north', 'the-bent-hazels', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-mist', 'east', 'the-cracked-oak', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wet-oaks', 'door', 'The Wet Oaks', 'The ground goes soft between the oaks here and holds water in every hollow, black and leaf-filled. The oaks do not mind it. Their roots stand up out of the wet like the legs of something wading.', 0, 0, 'wood', 0, -48, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-oaks', 'west', 'the-hornets-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-oaks', 'east', 'the-moss-tunnel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fungus-fall', 'door', 'The Fungus Fall', 'A fallen trunk lies here furred end to end with fungus, brackets and shelves and soft white fingers, some of it glowing faintly where the light is worst. The smell is sweet and wrong. The wood under it is no longer wood.', 0, 0, 'wood', 0, -52, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fungus-fall', 'east', 'the-wild-cherry', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fungus-fall', 'south', 'the-crows-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fungus-fall', 'north', 'the-stone-oak', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-holly-tree', 'door', 'The Holly Tree', 'A holly that has grown into a tree, forty feet of it, its lower limbs bare and its crown dark and dense. Beneath it the ground is carpeted in dead leaves that cut like glass through anything thinner than leather.', 0, 0, 'wood', 0, -51, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-tree', 'south', 'the-wild-cherry', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-black-alder-stand', 'door', 'The Black Alder Stand', 'Alders where the ground is wet, their trunks black and their roots red where the bark is broken, standing in water that never quite drains. It is colder here than it has any right to be. Breath shows.', 0, 0, 'wood', 0, -46, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-alder-stand', 'west', 'the-old-boundary-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-alder-stand', 'east', 'the-hazel-ride', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-leaf-drifts', 'door', 'The Leaf Drifts', 'The wind has piled the fallen leaves against the trunks here in drifts, knee-deep and higher, and between the drifts the ground is swept bare. You go round, and round, and round.', 0, 0, 'wood', 0, -43, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-leaf-drifts', 'west', 'the-hidden-spring', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-leaf-drifts', 'north', 'the-yew-shade', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-moss-boulders', 'door', 'The Moss Boulders', 'Boulders, big as carts, rounded and furred over with moss until they look soft, lying under the trees as if they had been rolled here and left. Ferns grow from the cracks in them.', 0, 0, 'wood', 0, -45, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moss-boulders', 'east', 'the-hidden-spring', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sunless-floor', 'door', 'The Sunless Floor', 'Under the trees here no light has reached the ground in living memory, and the floor is bare dark earth with nothing on it but the trunks and the dark between them. It is very cold, and very quiet.', 0, 0, 'wood', 0, -46, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunless-floor', 'east', 'the-old-pollards', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dappled-way', 'door', 'The Dappled Way', 'The canopy opens here and there in coin-sized holes, and the light comes down in spots that move when the crowns move, so the whole floor shifts and dapples and nothing is ever where it was.', 0, 0, 'wood', 0, -45, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dappled-way', 'north', 'the-old-pollards', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dappled-way', 'west', 'the-deer-browse', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ancient-ash', 'door', 'The Ancient Ash', 'An ash older than the oaks around it, its trunk a mass of burrs and hollows, its limbs dying back from the ends. It stands alone in a space of its own making, and the wood keeps its distance.', 0, 0, 'wood', 0, -44, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ancient-ash', 'north', 'the-great-root', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ancient-ash', 'south', 'the-rot-wood', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ancient-ash', 'west', 'the-ground-ivy', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cracked-oak', 'door', 'The Cracked Oak', 'Lightning took an oak here, long ago, and split it from crown to root without killing it. It grows on in two halves, the blackened wound between them wide enough to step into. Nothing grows in the wound.', 0, 0, 'wood', 0, -42, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cracked-oak', 'west', 'the-grey-mist', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cracked-oak', 'south', 'the-clean-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-moss-tunnel', 'door', 'The Moss Tunnel', 'The way runs between two banks grown so close with moss and fern overhead that it is a tunnel, green and dim and damp, with the drip of water somewhere along it. It bends. You cannot see either end.', 0, 0, 'wood', 0, -47, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moss-tunnel', 'west', 'the-wet-oaks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moss-tunnel', 'east', 'the-twisted-yews', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crows-oak', 'door', 'The Crows'' Oak', 'An oak taller than the rest, standing alone in a gap, its top limbs dead and white and lined with crows that watch you come and say so to each other. The ground under it is white with their droppings. They do not leave.', 0, 0, 'wood', 0, -52, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crows-oak', 'north', 'the-fungus-fall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crows-oak', 'west', 'the-soft-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-stone-oak', 'door', 'The Stone Oak', 'An oak has grown up through a heap of stones and taken them into itself, so the base of the trunk is half wood and half rock, the bark swelling over the edges of the stones. Whoever piled the stones, the oak has had them since.', 0, 0, 'wood', 0, -52, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-oak', 'south', 'the-fungus-fall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hazel-ride', 'door', 'The Hazel Ride', 'A ride was cut through here once and the hazel has come back along both its edges and met in the middle overhead, so it is a long green passage with a floor of nuts and husks. Squirrels have been at it. So has something heavier.', 0, 0, 'wood', 0, -45, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hazel-ride', 'west', 'the-black-alder-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hazel-ride', 'east', 'the-spring-mire', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-yew-shade', 'door', 'The Yew Shade', 'Yews, very old, their red trunks fluted and hollowed, their shade so dense that nothing at all grows beneath them. The floor is bare and soft with their needles. It is darker here than it should be.', 0, 0, 'wood', 0, -43, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-yew-shade', 'south', 'the-leaf-drifts', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-yew-shade', 'west', 'the-badger-banks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-deer-browse', 'door', 'The Deer Browse', 'Every leaf below the height of a deer''s reach has been eaten, so the trees here have bare trunks to a level line and green above it. The floor is trodden and scattered with droppings. They come through here often.', 0, 0, 'wood', 0, -46, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-browse', 'east', 'the-dappled-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deer-browse', 'south', 'the-snapped-limbs', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rot-wood', 'door', 'The Rot Wood', 'Everything fallen here is rotting at once, logs and limbs and whole trees soft to a kick, crawling with beetles and grubs. The smell is thick and sweet. The ground gives underfoot in places it should not.', 0, 0, 'wood', 0, -44, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rot-wood', 'north', 'the-ancient-ash', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rot-wood', 'south', 'the-thin-light', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rot-wood', 'west', 'the-sunk-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ground-ivy', 'door', 'The Ground Ivy', 'Ivy has covered everything here at ground level — stumps, stones, the roots and the floor between — in one dark glossy sheet, so the shape of the ground underneath it is a guess. The guess is wrong in places.', 0, 0, 'wood', 0, -45, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ground-ivy', 'east', 'the-ancient-ash', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-clean-floor', 'door', 'The Clean Floor', 'The floor here is swept clean to the earth, every leaf gone, as if something lay here or worked here or kept it this way on purpose. The trees around stand back from it. Nothing says what.', 0, 0, 'wood', 0, -42, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-clean-floor', 'north', 'the-cracked-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-clean-floor', 'west', 'the-wolf-run', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-twisted-yews', 'door', 'The Twisted Yews', 'Yews, black-green and ancient, their trunks wound round themselves like rope, growing in a tight group so close that their crowns are one crown. Under them is dark and dry and smells of resin. Nothing grows under a yew.', 0, 0, 'wood', 0, -46, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-twisted-yews', 'west', 'the-moss-tunnel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-twisted-yews', 'east', 'the-sapling-crowd', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-soft-floor', 'door', 'The Soft Floor', 'Moss over leaf over moss, years of it, a floor so soft and deep that every footstep goes in to the ankle without a sound and comes up slowly. It would hold a print for a week. It is holding several.', 0, 0, 'wood', 0, -53, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-soft-floor', 'east', 'the-crows-oak', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-soft-floor', 'north', 'the-bramble-tunnel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-spring-mire', 'door', 'The Spring Mire', 'A spring rises here into a soft green mire, the water welling up cold through moss that quakes when you step on it, running off between the roots in a dozen threads too small to name. The ground is wet for twenty paces round. Everything that lives out here comes to it.', 0, 0, 'wood', 0, -44, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-mire', 'west', 'the-hazel-ride', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-badger-banks', 'door', 'The Badger Banks', 'The ground is heaved up into banks and mounds, honeycombed with holes, the spoil heaps scattered with bones and bedding. The setts are older than anything else here but the trees.', 0, 0, 'wood', 0, -44, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-badger-banks', 'east', 'the-yew-shade', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-badger-banks', 'west', 'the-tangle', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-snapped-limbs', 'door', 'The Snapped Limbs', 'Big limbs lie on the floor here, fresh-broken, the wood pale where they split, as if something heavy came down through the crowns not long ago. Looking up, you cannot see what.', 0, 0, 'wood', 0, -46, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-snapped-limbs', 'north', 'the-deer-browse', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-thin-light', 'door', 'The Thin Light', 'The canopy thins here and a grey light comes down through it, enough to see by and no more. Everything is the same colour in it: trunks, floor, your hands. It is like walking in the moment before dawn, at any hour.', 0, 0, 'wood', 0, -44, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-light', 'north', 'the-rot-wood', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-light', 'east', 'the-fallen-crowns', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-light', 'south', 'the-buckled-ground', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sunk-way', 'door', 'The Sunk Way', 'A sunk way runs through the trees here, worn down below the floor by feet and carts a very long time ago, its banks overhung with roots. It goes in a straight line, which is more than anything else here does, and then it stops.', 0, 0, 'wood', 0, -45, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-way', 'east', 'the-rot-wood', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-way', 'south', 'the-holly-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wolf-run', 'door', 'The Wolf Run', 'A narrow trodden way runs along the floor here between the trunks, too low and too narrow for anything that walks upright, worn bare by a great many feet over a long time. It goes on in both directions.', 0, 0, 'wood', 0, -43, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wolf-run', 'east', 'the-clean-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sapling-crowd', 'door', 'The Sapling Crowd', 'Where an old tree fell, a hundred young ones have come up in the gap, thin and straight and close together, all reaching for the same light. You push through them and they spring back. The old tree lies under them, gone to earth.', 0, 0, 'wood', 0, -45, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sapling-crowd', 'west', 'the-twisted-yews', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sapling-crowd', 'north', 'the-holly-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bramble-tunnel', 'door', 'The Bramble Tunnel', 'Bramble arched over a way that something wide has kept open, so you walk in a green tunnel with thorns on every side and above. It turns twice. You come out of it not quite sure which way you went in.', 0, 0, 'wood', 0, -53, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bramble-tunnel', 'south', 'the-soft-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bramble-tunnel', 'north', 'the-ferny-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tangle', 'door', 'The Tangle', 'Windblown limbs, fallen branches and live growth come together here in a mass you climb over and under and through, and by the time you are out of it you could not have said how long it took.', 0, 0, 'wood', 0, -45, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tangle', 'east', 'the-badger-banks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tangle', 'west', 'the-silent-beeches', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tangle', 'north', 'the-dead-air', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fallen-crowns', 'door', 'The Fallen Crowns', 'The tops of two great trees came down together here and lie across each other in a mass of dead limbs and live growth, a thicket made in one night. The way goes under, through a gap something low has kept open.', 0, 0, 'wood', 0, -43, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-crowns', 'west', 'the-thin-light', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-crowns', 'east', 'the-oak-aisle', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-buckled-ground', 'door', 'The Buckled Ground', 'The floor rises and falls in short steep waves, the roots of the trees heaved up through it, so you go up and down and up again and never get anywhere level. It is tiring in a way that does not seem fair.', 0, 0, 'wood', 0, -44, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-buckled-ground', 'north', 'the-thin-light', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-buckled-ground', 'east', 'the-beech-mast', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-holly-wall', 'door', 'The Holly Wall', 'Holly grown up between the trunks into a wall, glossy and dark and armed, with only one gap in it you can see. The floor on either side is bare. Whatever made the gap is bigger than you and came through more than once.', 0, 0, 'wood', 0, -45, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-wall', 'north', 'the-sunk-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-wall', 'south', 'the-sapling-crowd', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ferny-bank', 'door', 'The Ferny Bank', 'A long bank, steep on one side, furred with fern and moss and the roots of the trees along its top. Water runs somewhere under it — you can hear it — but nowhere you can find.', 0, 0, 'wood', 0, -53, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferny-bank', 'south', 'the-bramble-tunnel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-silent-beeches', 'door', 'The Silent Beeches', 'Beeches again, tall and pale, and nothing else at all — no undergrowth, no birds, no sound. The floor is copper leaves. It could be any part of the wood. It could be the part you walked through already.', 0, 0, 'wood', 0, -46, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-silent-beeches', 'east', 'the-tangle', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-silent-beeches', 'north', 'the-wych-elms', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dead-air', 'door', 'The Dead Air', 'No wind reaches here. Not a leaf moves. The air is warm and close and smells of rot and green, and sound goes nowhere: a stick snapping underfoot is gone before it has finished.', 0, 0, 'wood', 0, -45, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-air', 'south', 'the-tangle', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-air', 'north', 'the-hornbeam-gloom', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-oak-aisle', 'door', 'The Oak Aisle', 'Two rows of oaks, so straight they might have been planted, running away from you with a clear floor between them like the aisle of some great dark building. The rows go further than you can see. They do not go anywhere.', 0, 0, 'wood', 0, -42, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-aisle', 'west', 'the-fallen-crowns', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-aisle', 'east', 'the-last-of-the-light', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-beech-mast', 'door', 'The Beech Mast', 'The floor here is all beech mast, the husks split and empty, piled in drifts that crunch underfoot and give off a dry brown smell. Something has been rooting through it. The drifts are turned over in long furrows.', 0, 0, 'wood', 0, -43, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beech-mast', 'west', 'the-buckled-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beech-mast', 'east', 'the-rotten-gate', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wych-elms', 'door', 'The Wych Elms', 'Elms, tall and rough-barked, the last of their kind out here, with the floor beneath them carpeted in their own pale winged seed. They creak in a wind you cannot feel at ground level.', 0, 0, 'wood', 0, -46, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wych-elms', 'south', 'the-silent-beeches', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wych-elms', 'north', 'the-moss-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wych-elms', 'west', 'the-high-crowns', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hornbeam-gloom', 'door', 'The Hornbeam Gloom', 'Old hornbeam, twisted and fluted like poured metal, with the light gone green under it. The trunks are cold to the hand. Everything here looks as if it has been here forever and means to stay.', 0, 0, 'wood', 0, -45, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hornbeam-gloom', 'south', 'the-dead-air', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hornbeam-gloom', 'north', 'the-ivy-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-last-of-the-light', 'door', 'The Last of the Light', 'A place where the light gives out — not dark, not yet, but going, as if the trees here had agreed among themselves to let in no more than they must. Your eyes ache with it. Further in is darker.', 0, 0, 'wood', 0, -41, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-of-the-light', 'west', 'the-oak-aisle', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-of-the-light', 'south', 'the-lime-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-of-the-light', 'north', 'the-murk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rotten-gate', 'door', 'The Rotten Gate', 'Two posts stand in the wood with nothing between them, and nothing either side, and nothing for a mile in any direction that a gate could have been keeping in or out. The posts are black and soft. One of them still has a hinge.', 0, 0, 'wood', 0, -42, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rotten-gate', 'west', 'the-beech-mast', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-moss-steps', 'door', 'The Moss Steps', 'The floor goes up in shallow steps of moss over buried stone, as if someone laid a stair here and the wood took it back. At the top, more of the same. At the bottom, the same.', 0, 0, 'wood', 0, -46, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moss-steps', 'south', 'the-wych-elms', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moss-steps', 'north', 'the-holly-dark', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-high-crowns', 'door', 'The High Crowns', 'The trees here are taller than anywhere else in the wood, the crowns so high and so close that the light down here is a dusk. The trunks are bare to a great height. Your neck aches from looking up.', 0, 0, 'wood', 0, -47, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-crowns', 'east', 'the-wych-elms', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-high-crowns', 'west', 'the-toadstool-ring', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ivy-wall', 'door', 'The Ivy Wall', 'Ivy has climbed a row of trees and hung itself between them in sheets, so the wood here has walls. Some of the walls have gaps in them. Some of the gaps go somewhere.', 0, 0, 'wood', 0, -45, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ivy-wall', 'south', 'the-hornbeam-gloom', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lime-stand', 'door', 'The Lime Stand', 'Limes, very old, each one a cluster of trunks grown up from a single stool, so the stand is a crowd of grey pillars with the light coming down between them in bars. Bees are in the crowns in summer. Now it is silent.', 0, 0, 'wood', 0, -41, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lime-stand', 'north', 'the-last-of-the-light', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-murk', 'door', 'The Murk', 'The trees crowd close and the canopy is three layers deep, and under it the air is brown and thick and smells of earth. You can see perhaps ten paces in any direction. Every direction looks like this.', 0, 0, 'wood', 0, -41, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-murk', 'south', 'the-last-of-the-light', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-holly-dark', 'door', 'The Holly Dark', 'Holly under the oaks, thick and dark and evergreen, so the floor beneath it is bare and dry and nearly black. You go through bent double. The leaves rattle when you touch them, and they do not stop rattling at once.', 0, 0, 'wood', 0, -46, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-dark', 'south', 'the-moss-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holly-dark', 'west', 'the-lichen-stones', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-toadstool-ring', 'door', 'The Toadstool Ring', 'A ring of pale toadstools on the leaf floor, wide enough to stand in, and others beyond it, and others beyond those, rings inside rings going off under the trees. The smell is sweet and wrong.', 0, 0, 'wood', 0, -48, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toadstool-ring', 'east', 'the-high-crowns', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toadstool-ring', 'west', 'the-cold-hollow-oaks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lichen-stones', 'door', 'The Lichen Stones', 'Stones lie about the floor here, grey and half sunk, each one furred with lichen in the same pale green. They might once have been a wall. They might once have been nothing.', 0, 0, 'wood', 0, -47, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lichen-stones', 'east', 'the-holly-dark', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lichen-stones', 'west', 'the-dead-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lichen-stones', 'south', 'the-grass-island', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cold-hollow-oaks', 'door', 'The Cold Hollow', 'A dip in the floor where the air pools cold even at midday, and the trees around it grow with a lean away from it. Mist sits in it until noon. The floor is damp and pale with mould.', 0, 0, 'wood', 0, -49, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-hollow-oaks', 'east', 'the-toadstool-ring', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dead-stand', 'door', 'The Dead Stand', 'A stand of trees that died standing, silver and bare, with fungus stepped up their sides in brackets. They have been dead long enough to be part of the wood now, and the living ones have grown up around them.', 0, 0, 'wood', 0, -48, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-stand', 'east', 'the-lichen-stones', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-stand', 'west', 'the-fern-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-stand', 'south', 'the-crooked-oaks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-grass-island', 'door', 'The Grass Island', 'Grass, in the middle of all this — a single lawn the size of a barn floor, ringed by holly so dense it might be a wall, cropped short by something that comes and goes. In the old growth that is a strange thing to find. It is open to the sky and closed to everything else, and you can see the whole of it from wherever you stand.', 0, 0, 'wood', 0, -47, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grass-island', 'north', 'the-lichen-stones', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fern-floor', 'door', 'The Fern Floor', 'Bracken, head-high, filling the space under the canopy edge to edge, so that once you are in it you can see nothing but fronds and the sky straight up. It closes behind you.', 0, 0, 'wood', 0, -49, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fern-floor', 'east', 'the-dead-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fern-floor', 'north', 'the-oak-knees', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crooked-oaks', 'door', 'The Crooked Oaks', 'Oaks bent by something — wind, or weight, or time — into shapes that lean and turn and reach, so no two of them grow the same way and none of them grow straight. Walking through them, you lose your line at once.', 0, 0, 'wood', 0, -48, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crooked-oaks', 'north', 'the-dead-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crooked-oaks', 'west', 'the-windthrow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-oak-knees', 'door', 'The Oak Knees', 'The roots of the oaks come up out of the ground here in knuckles and knees, and the way between them is a matter of stepping from one to the next. Moss on everything. The trunks go up out of sight.', 0, 0, 'wood', 0, -49, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-knees', 'south', 'the-fern-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-knees', 'west', 'the-green-ridge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oak-knees', 'north', 'the-burners-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-windthrow', 'door', 'The Windthrow', 'One storm, a long time ago, laid a whole stand down flat in the same direction, and the root plates stand on end around the edge like a palisade nobody built. The sky is open over it. Bramble and birch have come up through the fallen trunks, and inside the ring of roots the ground is sheltered from every wind but the one that did it.', 0, 0, 'wood', 0, -49, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-windthrow', 'east', 'the-crooked-oaks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-green-ridge', 'door', 'The Green Ridge', 'A trunk lies across the way, fallen so long ago that it is now a ridge of soft green earth with a row of young trees growing out of its back. Going round it takes longer than you would think.', 0, 0, 'wood', 0, -50, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-green-ridge', 'east', 'the-oak-knees', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-green-ridge', 'west', 'the-deep-litter', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-burners-flat', 'door', 'The Burners'' Flat', 'A circle of black ground forty paces across, where burners stacked their clamps for generations, so long ago that the trees have closed over it again from every side but not yet stepped onto it. Nothing grows on charcoal for a long time. It is level, it is dry, and it is the one place out here where a fire would look like it belonged.', 0, 0, 'wood', 0, -49, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-burners-flat', 'south', 'the-oak-knees', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-deep-litter', 'door', 'The Deep Litter', 'Old leaves, layer under layer, so deep that every step sinks to the ankle and comes up with the smell of a cellar. Under the trees it is dim at noon. The sound of your own feet is the only sound.', 0, 0, 'wood', 0, -51, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-litter', 'east', 'the-green-ridge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-litter', 'north', 'the-grey-trunks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-litter', 'west', 'the-split-ash', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-grey-trunks', 'door', 'The Grey Trunks', 'Beech, grey and smooth, standing in rows no hand planted, so far apart that you can see between them for a long way and so alike that seeing does you no good. The leaf litter is a foot deep and silent.', 0, 0, 'wood', 0, -51, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-trunks', 'south', 'the-deep-litter', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-trunks', 'east', 'the-root-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-grey-trunks', 'west', 'the-dark-pool', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-split-ash', 'door', 'The Split Ash', 'An ash that split down its length long ago and kept growing as two trees from one root, leaning apart. The way goes between them. On the far side the wood looks exactly as it did on this side.', 0, 0, 'wood', 0, -52, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-split-ash', 'east', 'the-deep-litter', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-split-ash', 'west', 'the-standing-oaks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-root-hollow', 'door', 'The Root Hollow', 'The ground drops into a hollow walled with roots, where the soil has washed out from under a row of trees and left them standing on their own legs. Under the roots it is dry. Above them it is the wood again.', 0, 0, 'wood', 0, -50, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-hollow', 'west', 'the-grey-trunks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-hollow', 'north', 'the-ward-oak', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dark-pool', 'door', 'The Dark Pool', 'A pool lies in a hollow among the roots, round and black and so still that the trunks stand in it upside down. Leaves float on it and do not move. At its edge the mud is printed deep with hooves and pads, all coming to the same place to drink, all going away again.', 0, 0, 'wood', 0, -52, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dark-pool', 'east', 'the-grey-trunks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dark-pool', 'west', 'the-moss-hall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-standing-oaks', 'door', 'The Standing Oaks', 'A ring of oaks, nine of them, each older than anything built by hand that still stands, grown so close at the crowns that the ring is a room with a green ceiling. The ground inside is bare and level and dry. Whoever planted them in a ring has been dead a thousand years, and the oaks have kept the floor swept ever since.', 0, 0, 'wood', 0, -53, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-standing-oaks', 'east', 'the-split-ash', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ward-oak', 'door', 'The Ward Oak', 'An oak stands across the way so broad that the path has to go round it, and on its bark, at the height of a man''s eye, a mark has been cut and cut again over years: the same mark, healed and recut, the newest cuts still pale. Past the oak the trees close in and the light goes. Nothing about the ground says to go on. Nothing says not to.', 0, 0, 'wood', 0, -50, -6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ward-oak', 'east', 'the-same-tree', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ward-oak', 'south', 'the-root-hollow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-moss-hall', 'door', 'The Moss Hall', 'A clearing roofed by the crowns of the trees around it and floored in moss so deep and even that it gives under you like a bed. A fallen oak lies along one side, gone soft and green from end to end, and the light that gets down here comes down slow. It is the quietest room in the world. Something could live here a long time and nothing would know.', 0, 0, 'wood', 0, -53, -5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-moss-hall', 'east', 'the-dark-pool', NULL);
