-- Generated by scripts/build-rooms.mjs from: regions/the-old-growth.rooms
-- 95 rooms, 188 exits. Do not hand-edit — regenerate from the source text.
-- Validated: every exit resolves, every exit has a return path (or is marked one-way),
-- no duplicate ids, no orphans, every room reachable from a gate.

-- FIRST: EVERY NAMELESS SPAWN GETS THE NAME IT ALREADY ANSWERS TO.
--
-- 340 mob_spawns rows carry a NULL id. The loader (world.ts) hands each one a
-- made-up id, spawn-<template>@<room>#<i>, where <i> is the row's place in
-- the whole table sorted by template, room, id — and the live world keys its
-- creatures, and its record of which dens are already seeded, by that id. So
-- ANY row added to the table, or any nameless row moved to another room,
-- shifts <i> for every nameless row sorted after it: their ids change, the
-- world reads those dens as new, seeds them again, and the population cap
-- culls the surplus — swapping living animals for fresh ones, wounds and
-- grudges and traits and all. Every migration that added spawns has done this.
--
-- So before this one adds or moves anything, each nameless row is written its
-- own current made-up id, computed here with the loader's exact ordering. The
-- live world sees no change at all, and nothing can shift these again.
--
-- The numbering is taken ONCE, into a scratch table, before any row changes.
-- Done in a single UPDATE it is not: each row's subquery sees the rows already
-- renamed, the order shifts under it, and two rows come out with the same name.
CREATE TABLE _spawn_freeze (r INTEGER PRIMARY KEY, new_id TEXT NOT NULL);
  SELECT rowid, 'spawn-' || template_id || '@' || room_id || '#' || (ROW_NUMBER() OVER (ORDER BY template_id, room_id, id) - 1)
  FROM mob_spawns;
UPDATE mob_spawns SET id = (SELECT f.new_id FROM _spawn_freeze f WHERE f.r = mob_spawns.rowid) WHERE id IS NULL;
DROP TABLE _spawn_freeze;

-- THE HEART'S DOOR MOVES. Done by hand because the builder only adds: the Grey
-- Scrub's door into the Close Dark comes out, and the woodward's seven rooms are
-- reached only from the far end of the fringe, past the Ward Oak into the Same
-- Tree (the file's attachment). The rooms of the heart do not move.
DELETE FROM exits WHERE (room_id = 'the-grey-scrub' AND dir = 'west' AND to_room = 'the-close-dark')
  OR (room_id = 'the-close-dark' AND dir = 'east' AND to_room = 'the-grey-scrub');

